function MapApp2(){

	let posts = [
		{ num : 1, title : '제목입니다', content : '내용입니다', writer : '홍길동'},
	]
	let body = posts.map((item, index, arr)=>{
		return;
	});
	
	return(
		
		<div>
			<form>
				<input type="text" placeholder="제목을 입력하세요."/>
				<br />
				<input type="text" placeholder="작성자를 입력하세요." />
				<br />
				<textarea placeholder="내용을 입력하세요."></textarea>
				<button>게시글 등록</button>
			</form>
			<h1>게시글 등록</h1>
			<table>
				<thead>
					<tr>
						<th>번호</th>
						<th>제목</th>
						<th>작성자</th>
					</tr>
					{
						posts.map((item, index, arr)=>{
							return (
							<tr>
								<th>{item.num}{item.index}</th>
								<th>{item.title}{index}</th>
								<th>{item.writer}{index}</th>
							</tr>
							)
						})
					}
				</thead>
				<tbody></tbody>
			</table>
		</div>
	);
}

export default MapApp2;
